"""Frozen public reference-text test of role-correct word-position contexts."""
import argparse
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from pathlib import Path

from vs import refcorpus

ROOT = Path(__file__).resolve().parent
PLAN_BYTES = (ROOT/'plan.json').read_bytes()
PLAN = json.loads(PLAN_BYTES)
METHODS = ('unconditioned', 'position_all', 'position_info')
TOL = 1e-12


def save(name, value):
    (ROOT/name).write_bytes((json.dumps(value, indent=2)+'\n').encode())


def sha(data):
    return hashlib.sha256(data).hexdigest()


def js(p, q):
    np, nq = sum(p.values()), sum(q.values())
    assert np and nq
    total = 0.0
    for s in sorted(p.keys() | q.keys()):
        x, y = p[s]/np, q[s]/nq
        middle = (x+y)/2
        if x:
            total += x*math.log2(x/middle)/2
        if y:
            total += y*math.log2(y/middle)/2
    return total


def cell():
    return {'n': 0, 'left': Counter(), 'right': Counter()}


class Context:
    def __init__(self, text):
        self.positions = defaultdict(lambda: defaultdict(cell))
        self.all = defaultdict(cell)
        for word in text.split():
            for i, c in enumerate(word):
                key = (i == 0, i == len(word)-1)
                before = word[i-1] if i else ' '
                after = word[i+1] if i+1 < len(word) else ' '
                for record in (self.positions[c][key], self.all[c]):
                    record['n'] += 1
                    record['left'][before] += 1
                    record['right'][after] += 1

    def scores(self, c, a, b):
        out = dict.fromkeys(METHODS)
        if any(self.all[s]['n'] < 40 for s in (c, a, b)):
            return out
        out['unconditioned'] = (js(self.all[c]['left'], self.all[a]['left'])+
                                js(self.all[c]['right'], self.all[b]['right']))/2
        for method in ('position_all', 'position_info'):
            numerator = 0.0
            denominator = informative_occurrences = 0
            supported = True
            for (initial, final), record in self.positions[c].items():
                directions = []
                if method == 'position_all' or not initial:
                    directions.append(('left', self.positions[a][initial, False]))
                if method == 'position_all' or not final:
                    directions.append(('right', self.positions[b][False, final]))
                if directions:
                    informative_occurrences += record['n']
                for direction, reference in directions:
                    if reference['n'] < 20:
                        supported = False
                        break
                    numerator += record['n']*js(record[direction], reference[direction])
                    denominator += record['n']
                if not supported:
                    break
            if supported and denominator and (method != 'position_info' or informative_occurrences >= 40):
                out[method] = numerator/denominator
        return out


def source(language, partition):
    loader, offset = {
        'calibration': (refcorpus.calib_text, 40000),
        'evaluation': (refcorpus.control_text, 80000),
        'training': (refcorpus.train_text, 40000),
        'old_evaluation': (refcorpus.control_text, 40000),
    }[partition]
    text = ' '.join(loader(language))[offset:].split(' ', 1)[1]
    return ' '+text[:40000].rsplit(' ', 1)[0]+' '


def pool(text, target, decoy, mode, seed):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            pair = word[i:i+2]
            if pair not in (target, decoy):
                continue
            start = offset+i
            key = (i == 0, i+2 == len(word))
            if mode in ('left', 'both'):
                key += (text[start-1],)
            if mode == 'both':
                key += (text[start+2],)
            groups[key][pair == decoy].append(start)
        offset += len(word)+1
    rng = random.Random(seed)
    blocked, pairs = set(), []
    for key, (true, wrong) in sorted(groups.items()):
        rng.shuffle(true)
        rng.shuffle(wrong)
        for i, j in zip(true, wrong):
            if abs(i-j) < 3 or i in blocked or j in blocked:
                continue
            pairs.append((i, j))
            blocked.update(range(i-2, i+3))
            blocked.update(range(j-2, j+3))
    rng.shuffle(pairs)
    return pairs


def plant(text, pairs):
    edits = sorted([(i, 'X') for i, j in pairs]+[(j, 'Z') for i, j in pairs])
    pieces, previous = [], 0
    for i, c in edits:
        pieces += [text[previous:i], c]
        previous = i+2
    pieces.append(text[previous:])
    return ''.join(pieces)


def trial(text, language, target, decoy, mode, fraction, seed, partition):
    matched = pool(text, target, decoy, mode, seed)
    pairs = matched[:len(matched)//2] if fraction == .5 else matched
    calc = Context(plant(text, pairs))
    assert calc.all['X']['n'] == calc.all['Z']['n'] == len(pairs)
    for i, j in pairs:
        assert text[i:i+2] == target and text[j:j+2] == decoy
        assert (text[i-1] == ' ', text[i+2] == ' ') == (text[j-1] == ' ', text[j+2] == ' ')
        if mode in ('left', 'both'):
            assert text[i-1] == text[j-1]
        if mode == 'both':
            assert text[i+2] == text[j+2]
    x, z = calc.scores('X', *target), calc.scores('Z', *target)
    if mode == 'both':
        for m in METHODS:
            assert (x[m] is None) == (z[m] is None)
            assert x[m] is None or abs(x[m]-z[m]) <= TOL
    return {'language': language, 'partition': partition, 'target': target, 'decoy': decoy,
            'mode': mode, 'fraction': fraction, 'seed': seed, 'pairs': len(pairs),
            'scores': {'X': x, 'Z': z},
            'common_eligible': all(x[m] is not None and z[m] is not None for m in METHODS),
            'candidate_position_counts': {str(key): record['n'] for key, record in calc.positions['X'].items()}}


def paired(partition):
    rows, sources = [], []
    for language, contrasts in PLAN['primary_contrasts'].items():
        text = source(language, partition)
        sources.append({'language': language, 'characters': len(text), 'sha256': sha(text.encode())})
        for target, decoy in contrasts:
            for mode in PLAN['matching_modes']:
                for fraction in PLAN['fractions']:
                    for seed in PLAN['seeds']:
                        rows.append(trial(text, language, target, decoy, mode, fraction, seed, partition))
    return rows, sources


def primary(rows):
    return [r for r in rows if r['mode'] == 'left' and r['fraction'] == 1 and r['common_eligible']]


def accept(score, threshold):
    return score is not None and threshold is not None and score < threshold-TOL


def summarize(rows, thresholds):
    out = []
    for mode in PLAN['matching_modes']:
        for fraction in PLAN['fractions']:
            selected = [r for r in rows if r['mode'] == mode and r['fraction'] == fraction]
            common = [r for r in selected if r['common_eligible']]
            methods = {}
            for m in METHODS:
                count = Counter({'genuine_win': 0, 'decoy_win': 0, 'tie': 0, 'accepted_X': 0, 'accepted_Z': 0})
                for r in common:
                    x, z = r['scores']['X'][m], r['scores']['Z'][m]
                    count['genuine_win' if x < z-TOL else 'decoy_win' if z < x-TOL else 'tie'] += 1
                    count['accepted_X'] += accept(x, thresholds[m])
                    count['accepted_Z'] += accept(z, thresholds[m])
                methods[m] = dict(count)
            out.append({'mode': mode, 'fraction': fraction, 'attempted': len(selected),
                        'common_eligible': len(common),
                        'supported_by_method': {m: sum(all(r['scores'][c][m] is not None for c in ('X', 'Z')) for r in selected) for m in METHODS},
                        'methods': methods})
    return out


def negatives(thresholds):
    rows = []
    for language, contrasts in PLAN['primary_contrasts'].items():
        evaluation = source(language, 'evaluation')
        streams = [('natural', None, evaluation)]
        train = source(language, 'training').strip()
        outgoing = defaultdict(Counter)
        for a, b in zip(train, train[1:]):
            outgoing[a][b] += 1
        starts = Counter(w[0] for w in train.split())
        def draw(rng, counts):
            point = rng.randrange(sum(counts.values()))
            for c, n in sorted(counts.items()):
                if point < n:
                    return c
                point -= n
            raise AssertionError('draw')
        for seed in PLAN['chain_seeds']:
            rng = random.Random(seed)
            letters = [draw(rng, starts)]
            while len(letters) < len(evaluation)-2:
                choices = outgoing[letters[-1]]
                if len(letters) == len(evaluation)-3:
                    choices = Counter({s: n for s, n in choices.items() if s != ' '})
                letters.append(draw(rng, choices or starts))
            streams.append(('direct_chain', seed, ' '+''.join(letters)+' '))
        for origin, seed, text in streams:
            calc = Context(text)
            for target, _ in contrasts:
                candidates = []
                for c in sorted(calc.all):
                    if c in target or not c.islower() or calc.all[c]['n'] < 40:
                        continue
                    values = calc.scores(c, *target)
                    candidates.append({'candidate': c, 'scores': values,
                                       'accepted': {m: accept(values[m], thresholds[m]) for m in METHODS}})
                rows.append({'language': language, 'origin': origin, 'seed': seed, 'target': target,
                             'characters': len(text), 'sha256': sha(text.encode()), 'candidates': candidates})
    return rows


def diagnostic(thresholds):
    rows = []
    for partition, seeds in [('old_evaluation', [58471, 58477, 58481, 58487, 58493]),
                             ('evaluation', PLAN['seeds'])]:
        text = source('latin', partition)
        for seed in seeds:
            row = trial(text, 'latin', 'us', 'um', 'left', 1, seed, partition)
            row['source_sha256'] = sha(text.encode())
            row['accepted'] = {c: {m: accept(row['scores'][c][m], thresholds[m]) for m in METHODS} for c in ('X', 'Z')}
            rows.append(row)
    text = ' '.join(['x ab aba bab']*100)
    scores = Context(text).scores('x', 'a', 'b')
    assert scores['position_all'] == 0 and scores['position_info'] is None
    return {'us_um': rows, 'boundary_trap': {'text_recipe': 'x ab aba bab repeated 100 times', 'scores': scores,
            'accepted': {m: accept(scores[m], thresholds[m]) for m in METHODS}}}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=('calibrate', 'evaluate'))
    phase = parser.parse_args().phase
    if phase == 'calibrate':
        rows, sources = paired('calibration')
        supported = primary(rows)
        thresholds = {}
        for m in METHODS:
            scores = sorted(r['scores']['Z'][m] for r in supported)
            thresholds[m] = scores[math.floor(.05*len(scores))] if scores else None
        output = {'plan_sha256': sha(PLAN_BYTES), 'script_sha256': sha(Path(__file__).read_bytes()),
                  'thresholds': thresholds, 'calibration_negative_count': len(supported), 'sources': sources,
                  'summary': summarize(rows, thresholds), 'paired_rows': rows}
        name = 'calibration.json'
    else:
        frozen = (ROOT/'calibration.json').read_bytes()
        calibration = json.loads(frozen)
        assert calibration['plan_sha256'] == sha(PLAN_BYTES)
        assert calibration['script_sha256'] == sha(Path(__file__).read_bytes())
        thresholds = calibration['thresholds']
        rows, sources = paired('evaluation')
        output = {'plan_sha256': sha(PLAN_BYTES), 'calibration_sha256': sha(frozen), 'thresholds': thresholds,
                  'sources': sources, 'summary': summarize(rows, thresholds), 'paired_rows': rows,
                  'negative_controls': negatives(thresholds), 'diagnostics': diagnostic(thresholds)}
        name = 'evaluation.json'
    save(name, output)
    print(json.dumps({'phase': phase, 'primary_common': len(primary(rows)), 'thresholds': thresholds,
                      'summary': output['summary']}, indent=2))


if __name__ == '__main__':
    main()
